/* Generated by build-offline.mjs. Only the public catalogue and static assets are cached. */
const VERSION = '__FULLVIEW_CACHE_VERSION__';
const SHELL = `fullview-shell-${VERSION}`;
const STATIC = `fullview-static-${VERSION}`;
const PRECACHE = ['/offline.html','/offline.css','/offline.js','/estimate-pdf.js','/brand/logo-dark.png','/fonts/instrument-serif-regular.ttf','/offline-catalogue.json','/favicon.svg','/brand/icon-192.png','/brand/icon-512.png','/brand/logo-light.svg','/fonts/dm-sans-regular.ttf','/fonts/dm-sans-semibold.ttf','/fonts/libre-caslon-display.ttf'];

self.addEventListener('install', event => {
  event.waitUntil(caches.open(SHELL).then(cache => cache.addAll(PRECACHE.map(url => new Request(url, { cache: 'reload' })))));
});
self.addEventListener('activate', event => {
  event.waitUntil(caches.keys().then(keys => Promise.all(keys.filter(key => (key.startsWith('fullview-shell-') || key.startsWith('fullview-static-')) && ![SHELL, STATIC].includes(key)).map(key => caches.delete(key)))).then(() => self.clients.claim()));
});
self.addEventListener('message', event => {
  if (event.data?.type === 'SKIP_WAITING') self.skipWaiting();
});

self.addEventListener('fetch', event => {
  const request = event.request;
  const url = new URL(request.url);
  if (request.method !== 'GET' || url.origin !== self.location.origin) return;
  // Private research briefs, sign-in, account pages and RSC data never enter Cache Storage.
  if (/^\/(api|workspace|signin-with-chatgpt|signout-with-chatgpt|callback)(\/|$)/.test(url.pathname) || url.searchParams.has('_rsc') || request.headers.has('RSC')) return;
  if (request.mode === 'navigate') {
    event.respondWith(fetch(request).catch(async () => (await (await caches.open(SHELL)).match('/offline.html')) || new Response('Please reconnect to open Fullview Signature.', { status: 503, headers: { 'Content-Type': 'text/plain; charset=utf-8' } })));
    return;
  }
  if (!/^\/(brand|fonts|services\/photography|_next\/static)\//.test(url.pathname) && !PRECACHE.includes(url.pathname)) return;
  event.respondWith((async () => {
    const shell = await caches.open(SHELL);
    const prefetched = await shell.match(request);
    if (prefetched) return prefetched;
    const cache = await caches.open(STATIC);
    const hit = await cache.match(request);
    if (hit) return hit;
    const response = await fetch(request);
    const policy = response.headers.get('Cache-Control') || '';
    if (response.ok && response.type === 'basic' && !/no-store|private/i.test(policy)) {
      try {
        await cache.put(request, response.clone());
        const keys = await cache.keys();
        if (keys.length > 140) await Promise.all(keys.slice(0, keys.length - 140).map(key => cache.delete(key)));
      } catch { /* A full device cache must not interrupt a successful network response. */ }
    }
    return response;
  })());
});
